          "stepType": "TextOutput",
          "name": "Limit Reached",
          "secure": false,
          "value": [
            {
              "value": "(function execute() {\n    /* Return a quoted string.  For example:\n\n       if (vaInputs.first_name == 'Bill') {\n           return gs.getMessageLang(\"hi there {0}\", vaContext.getRequesterLang(), [vaInputs.first_name]);\n       } else {\n           return gs.getMessageLang(\"how are you {0}\", vaContext.getRequesterLang(), [vaInputs.last_name]);\n       }\n    */\n    if(vaSystem.isLiveAgentAvailable()){\n        return 'You have reached your NeedIt search limit. I will transfer you to a live agent for assistance.'\n    }else{\n        return 'You have reached your NeedIt search limit. If you need to work with multiptle NeedIt records, open NeedIt > My NeedIt Requestes.'\n    }\n})()\n",
              "mode": "script"
            }
          ],
          "isCollapsible": true,
          "requestFeedback": true,
